ROOT=Path(__file__).parent
DIST=ROOT/'dist'
RESEARCH=ROOT.parent/'website-research'
INVENTORY=json.loads((ROOT/'content-source/preservation-inventory.json').read_text())
PROOF={x['id']:x for x in INVENTORY['proof_items']}
for x in PROOF.values():
    src=Path(x.get('local_poster_path') or x.get('local_image_path'))
    if not src.exists(): continue
    target=DIST/'assets'/('proof-'+x['id']+'.webp')
    original=DIST/'assets'/'volvo-feedback-original.png'
    if x['id']=='volvo-feedback' and not original.exists(): shutil.copy2(src,original)
    # Retain prepared source evidence byte-for-byte during page-only rebuilds.
    if target.exists() and target.stat().st_size: continue
    im=Image.open(src).convert('RGB'); im.thumbnail((1400,1000))
    temporary=target.with_suffix('.tmp')
    im.save(temporary,format='WEBP',quality=85)
    if not temporary.stat().st_size: raise ValueError('Empty proof image: '+str(src))
    temporary.replace(target)
