def interactive(slug):
    if slug not in ['dimaq','dealtailor']:return ''
    if slug=='dimaq':
        title='Ask a bigger business question.'; tabs=['Finance','Sales','Operations']; data=[('Where might cash collection need attention?','Relate overdue receivables, disputes and customer commitments within your permitted records.','Evidence to examine','Invoice ageing · disputes · promised payment dates','Possible next step','Prioritise an account review and validate the cause with its owner.'),('Which customer commitments could be at risk?','Connect open orders with availability, planned supply and promised dates.','Evidence to examine','Order lines · available stock · supply commitments','Possible next step','Review at-risk commitments with sales and operations.'),('What keeps the same issue coming back?','Explore recurring exceptions across incidents, process steps and operational context.','Evidence to examine','Exception history · ownership · process dependencies','Possible next step','Bring a recurring pattern to the review and assign an investigation.')]
    else:
        title='From enquiry to an informed handover.';tabs=['Understand','Engage','Progress'];data=[('Start with the lead’s context.','Use the enquiry, campaign and approved knowledge to understand the person’s business need.','Context to consider','Business need · conversation history · campaign intent','Human responsibility','Approve the knowledge, data permissions and engagement boundaries.'),('Make the next reply relevant.','Answer from approved business content and clarify the information needed to move forward.','Conversation priorities','Fit · intent · urgency · missing information','Human responsibility','Review escalation routes and any sensitive or exceptional requests.'),('Give sales a useful next step.','Bring the conversation, qualification context and recommended action into the configured handover.','Possible next steps','Demo · meeting · follow-up · human assistance','Human responsibility','Sales decides how to progress the opportunity.')]
    buttons=''.join(f'<button role="tab" id="tab-{i}" aria-controls="panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}">{t}</button>' for i,t in enumerate(tabs))
    panels=''.join(f'<div id="panel-{i}" role="tabpanel" aria-labelledby="tab-{i}" {"hidden" if i else ""}><div class="interactive-content"><div><p class="example-label">{tabs[i]} / illustrative example</p><h3>{a}</h3><p>{b}</p></div><div class="evidence-block"><h4>{c}</h4><p>{d}</p><h4>{e}</h4><p>{f}</p></div></div></div>' for i,(a,b,c,d,e,f) in enumerate(data))
    return f'<section class="section tinted"><div class="wrap"><div class="section-head"><div><p class="eyebrow">EXPLORE THE APPROACH</p><h2>{title}</h2></div></div><div class="interactive-panel" data-tabs><div class="interaction-tabs" role="tablist" aria-label="Illustrative {slug} workflow">{buttons}</div>{panels}<p class="example-note">Illustrative workflow, not a live product response. Actual behaviour depends on approved sources, integrations, scope and permissions.</p></div></div></section>'
