def ai_streams():
    streams=[('01','AI Application Developer','Make AI useful, reliable and controlled.','ai-application',['Frame the task, approved data and success checks.','Develop prompts, model API calls and predictable output formats.','Retrieve approved knowledge and support answers with citations.','Connect tools with permissions, human approval and recovery paths.','Evaluate answer quality, security, response time and model usage cost.','Build, deploy and monitor a usable AI application.'],'A policy assistant that cites approved sources and routes uncertain cases to staff.'),('02','AI-powered Full-Stack Developer','Build the complete application people use.','full-stack',['Map user journeys, application behaviour and data.','Build accessible screens, forms and mobile-friendly interfaces.','Implement business rules, APIs, SQL records, sign-in and permissions.','Integrate AI where it improves the user’s task.','Test complete flows, data changes, permissions and failure cases.','Deploy, maintain and improve the application using logs and feedback.'],'A returns portal with customer screens, staff approval, records and a policy assistant.')]
    panels=''.join(f'<article class="split-panel"><p class="eyebrow">STREAM {n}</p>{img(im,"Conceptual illustration of "+title)}<h3>{title}</h3><p class="stream-lede">{tag}</p><ol class="clean-list">'+''.join(f'<li>{item}</li>' for item in items)+f'</ol><div class="stream-example"><b>Example outcome</b><p>{example}</p></div></article>' for n,title,tag,im,items,example in streams)
    rows=[('Main responsibility','Reliable AI behaviour in a defined task.','The complete application and user journey.'),('Deeper practice','Prompts, retrieval, tool use and evaluation.','Screens, server logic, data and reliable releases.'),('Primary checks','Supported answers, safe actions, response time and model cost.','Correct flows, safe data, access boundaries and reliable releases.'),('Shared practice','Both streams build, test, deploy and explain their work.','Both use AI with human review, documented decisions and responsible data handling.')]
    inds=[('Retail & e-commerce','Policy assistants; returns and order portals.'),('Banking & insurance','Internal-policy guidance; document and approval workflows.'),('Manufacturing','SOP retrieval; quality and maintenance applications.'),('Logistics & supply chain','Exception summaries; tracking and operations portals.'),('Healthcare administration','Service FAQs; non-clinical appointment workflows.'),('Education & training','Course assistants; learner and review applications.'),('Professional services','Knowledge assistants; client case applications.'),('Hospitality & real estate','Enquiry assistants; booking and service portals.')]
    return f'''<section class="section tinted" id="streams"><div class="wrap"><div class="section-head"><div><p class="eyebrow">CHOOSE YOUR AREA OF DEPTH</p><h2>Two streams.<br>Two clear responsibilities.</h2></div><p class="lede">Both build working software. One goes deeper into AI behaviour; the other into the complete application.</p></div><div class="split-panels">{panels}</div><div class="table-scroll"><table class="comparison"><caption>Compare the streams</caption><thead><tr><th scope="col">Area</th><th scope="col">AI Application Developer</th><th scope="col">AI-powered Full-Stack</th></tr></thead><tbody>{''.join(f'<tr><th scope="row">{a}</th><td>{b}</td><td>{c}</td></tr>' for a,b,c in rows)}</tbody></table></div></div></section><section class="section light"><div class="wrap"><div class="overview-layout"><div class="overview-copy"><p class="eyebrow">THE COMMON FOUNDATION</p><h2>Experience you can explain. Evidence you can show.</h2><p class="lede">Both streams start with a real user, a defined problem and a useful outcome. AI supports the work; you remain responsible for reviewing, testing and explaining it.</p></div><div class="feature-list">{''.join(f'<div class="feature-item"><span class="num">0{i+1}</span><div><h3>{a}</h3><p>{b}</p></div></div>' for i,(a,b) in enumerate([('Problem & working demo','Show the brief, scope, deployed solution and main user task.'),('Code & contribution','Explain your Git history, decisions and the parts you built or changed.'),('Tests & feedback','Present quality results, difficult cases, revisions and remaining limits.'),('Responsible handover','Document setup, permissions, data handling and operating notes.')]))}</div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">POTENTIAL INDUSTRY CONTEXTS</p><h2>Apply your work<br>to a business need.</h2></div><p class="lede">Illustrative project contexts. Allocation depends on scope, data access and supervision.</p></div><div class="industry-grid">{''.join(f'<span><b>{a}</b><small>{b}</small></span>' for a,b in inds)}</div><div class="section-head career-head"><div><p class="eyebrow">GLOBAL CAREER PATHWAYS</p><h2>Demonstrate capability.<br>Explore the opportunity.</h2></div><p class="lede">Potential roles include AI application, AI integration, full-stack, backend and software application development.</p></div><div class="phase-grid">{''.join(f'<div class="phase-card"><h3>{a}</h3><p>{b}</p></div>' for a,b in [('Permanent','Contribute to ongoing development in a product, IT or enterprise team.'),('Contract','Deliver a defined integration, project or release within an agreed period.'),('Freelance','Take on scoped assistants, portals or workflows with clear acceptance and handover.')])}</div><div class="scope-box"><h3>Markets &amp; readiness</h3><p>Explore India and wider Asia-Pacific, the GCC, Europe/UK and North America. Match on-site, hybrid or remote opportunities to work eligibility, time zones and demonstrated skills. Employer recognition and role level depend on the relevance and depth of your work, prior skills and employer or client selection. There is no employment or universal industry-recognition guarantee.</p></div></div></section>'''
